class Calculator:
    def __init__(self):
        pass

    def add(self, num1, num2):
        return num1 + num2

    def subtract(self, num1, num2):
        return num1 - num2

    def multiply(self, num1, num2):
        return num1 * num2

    def divide(self, num1, num2):
        if num2 != 0:
            return num1 / num2
        else:
            return "Error: Division by zero is not allowed"

def main():
    calculator = Calculator()
    print("Simple Calculator")
    print("1. Addition")
    print("2. Subtraction")
    print("3. Multiplication")
    print("4. Division")

    choice = input("Enter your choice (1/2/3/4): ")

    if choice in ('1', '2', '3', '4'):
        num1 = float(input("Enter first number: "))
        num2 = float(input("Enter second number: "))

        if choice == '1':
            print(num1, "+", num2, "=", calculator.add(num1, num2))
        elif choice == '2':
            print(num1, "-", num2, "=", calculator.subtract(num1, num2))
        elif choice == '3':
            print(num1, "*", num2, "=", calculator.multiply(num1, num2))
        elif choice == '4':
            print(num1, "/", num2, "=", calculator.divide(num1, num2))
    else:
        print("Invalid choice")

if __name__ == "__main__":
    main()
```

This code creates a simple calculator that performs addition, subtraction, multiplication, and division. The user is prompted to choose an operation and enter two numbers. The result is then printed to the console.
